import json, os, re
from collections import deque

ROOT_DIR = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
PKG_PREFIX = "AlgebraicJacobian"
ROOT_MODULE = "AlgebraicJacobian"
import_re = re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)\s*$')

def module_name_for_path(path):
    rel = os.path.relpath(path, ROOT_DIR)[:-len(".lean")]
    return rel.replace(os.sep, ".")

all_files = []
for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT_DIR, PKG_PREFIX)):
    for fn in filenames:
        if fn.endswith(".lean"):
            all_files.append(os.path.join(dirpath, fn))
root_file = os.path.join(ROOT_DIR, PKG_PREFIX + ".lean")
if os.path.isfile(root_file):
    all_files.append(root_file)

all_modules = set(module_name_for_path(p) for p in all_files)
imports = {}
for p in all_files:
    mod = module_name_for_path(p)
    imps = []
    with open(p, errors="replace") as f:
        for line in f:
            m = import_re.match(line)
            if m:
                imps.append(m.group(1))
    imports[mod] = [i for i in imps if i == PKG_PREFIX or i.startswith(PKG_PREFIX+".")]

visited = {ROOT_MODULE}
q = deque([ROOT_MODULE])
while q:
    cur = q.popleft()
    for nxt in imports.get(cur, []):
        if nxt not in visited:
            visited.add(nxt)
            q.append(nxt)
reachable = visited & all_modules

for mod in ["AlgebraicJacobian.Picard.Pic0ChartUnivReduce", "AlgebraicJacobian.Picard.Pic0ChartRestrictedFibre", "AlgebraicJacobian.Picard.Pic0ChartLocusFibreGuard", "AlgebraicJacobian.Picard.Pic0ChartAtlasCoupling"]:
    print(mod, "ROOTED" if mod in reachable else "UNROOTED", "EXISTS" if mod in all_modules else "MISSING")
print("total:", len(all_modules), "reachable:", len(reachable), "unrooted:", len(all_modules-reachable))
